TABLE_SQL = "\nCREATE TABLE structured_strategy_versions (\n\tid UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tparent_version_id UUID, \n\tprogram JSONB NOT NULL, \n\tprogram_canonical TEXT NOT NULL, \n\tprogram_sha256 VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (owner_id, id), \n\tFOREIGN KEY(owner_id) REFERENCES users (id), \n\tFOREIGN KEY(owner_id, parent_version_id) REFERENCES structured_strategy_versions (owner_id, id), \n\tCHECK (program_sha256 ~ '^[a-f0-9]{64}$' AND octet_length(program_canonical) BETWEEN 1 AND 65536 AND jsonb_typeof(program)='object')\n)\n\n\n;\n\nCREATE TABLE structured_strategy_specs (\n\trun_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tstructured_strategy_version_id UUID NOT NULL, \n\tconfig JSONB NOT NULL, \n\tconfig_canonical TEXT NOT NULL, \n\tconfig_sha256 VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (run_id), \n\tUNIQUE (owner_id, run_id), \n\tFOREIGN KEY(owner_id, run_id) REFERENCES research_runs (owner_id, id), \n\tFOREIGN KEY(owner_id, structured_strategy_version_id) REFERENCES structured_strategy_versions (owner_id, id), \n\tCHECK (config_sha256 ~ '^[a-f0-9]{64}$' AND octet_length(config_canonical) BETWEEN 1 AND 1048576 AND jsonb_typeof(config)='object')\n)\n\n\n;\n\nCREATE TABLE factor_strategy_executions (\n\tid UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tordinal INTEGER NOT NULL, \n\tstructured_strategy_version_id UUID NOT NULL, \n\tsnapshot_id UUID NOT NULL, \n\tfactor_version_id UUID NOT NULL, \n\tstrategy_input JSONB NOT NULL, \n\tstrategy_input_canonical TEXT NOT NULL, \n\tstrategy_input_sha256 VARCHAR(64) NOT NULL, \n\tstrategy_input_size_bytes BIGINT NOT NULL, \n\tmarket_sha256 VARCHAR(64) NOT NULL, \n\tmarket_size_bytes BIGINT NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (owner_id, run_id, attempt_id, generation, id), \n\tUNIQUE (owner_id, id), \n\tUNIQUE (run_id, ordinal), \n\tUNIQUE (run_id, snapshot_id), \n\tFOREIGN KEY(owner_id, run_id) REFERENCES structured_strategy_specs (owner_id, run_id), \n\tFOREIGN KEY(run_id, generation, attempt_id) REFERENCES execution_attempts (run_id, generation, id), \n\tFOREIGN KEY(owner_id, structured_strategy_version_id) REFERENCES structured_strategy_versions (owner_id, id), \n\tFOREIGN KEY(owner_id, snapshot_id) REFERENCES factor_execution_snapshot_outcomes (owner_id, publication_id), \n\tFOREIGN KEY(owner_id, factor_version_id) REFERENCES factor_versions (owner_id, id), \n\tCHECK (generation=1 AND ordinal BETWEEN 0 AND 1 AND strategy_input_sha256 ~ '^[a-f0-9]{64}$' AND market_sha256 ~ '^[a-f0-9]{64}$' AND strategy_input_size_bytes BETWEEN 1 AND 1048576 AND octet_length(strategy_input_canonical)=strategy_input_size_bytes AND jsonb_typeof(strategy_input)='object' AND market_size_bytes BETWEEN 1 AND 33554432)\n)\n\n\n;\n\nCREATE TABLE factor_strategy_execution_outcomes (\n\texecution_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tadmission_id UUID NOT NULL, \n\tlaunch_identity_receipt_id UUID NOT NULL, \n\tlaunch_identity_kind VARCHAR(30) NOT NULL, \n\tlaunch_identity_sha256 VARCHAR(64) NOT NULL, \n\tstop_receipt_id UUID NOT NULL, \n\tstop_kind VARCHAR(30) NOT NULL, \n\tstop_sha256 VARCHAR(64) NOT NULL, \n\textraction_receipt_id UUID NOT NULL, \n\textraction_kind VARCHAR(30) NOT NULL, \n\textraction_sha256 VARCHAR(64) NOT NULL, \n\tresult JSONB NOT NULL, \n\tresult_canonical TEXT NOT NULL, \n\tresult_sha256 VARCHAR(64) NOT NULL, \n\tresult_size_bytes BIGINT NOT NULL, \n\tdecision_count INTEGER NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (execution_id), \n\tUNIQUE (owner_id, run_id, attempt_id, generation, execution_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, execution_id) REFERENCES factor_strategy_executions (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id) REFERENCES research_process_admissions (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id, launch_identity_receipt_id, launch_identity_kind) REFERENCES research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tCHECK (launch_identity_kind='launch_identity'), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id, stop_receipt_id, stop_kind) REFERENCES research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tCHECK (stop_kind='stop'), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, admission_id, extraction_receipt_id, extraction_kind) REFERENCES research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tCHECK (extraction_kind='extraction'), \n\tCHECK (generation=1 AND result_sha256 ~ '^[a-f0-9]{64}$' AND launch_identity_sha256 ~ '^[a-f0-9]{64}$' AND stop_sha256 ~ '^[a-f0-9]{64}$' AND extraction_sha256 ~ '^[a-f0-9]{64}$' AND result_size_bytes BETWEEN 1 AND 16777216 AND octet_length(result_canonical)=result_size_bytes AND jsonb_typeof(result)='object' AND decision_count BETWEEN 1 AND 8), \n\tUNIQUE (admission_id)\n)\n\n\n;\n\nCREATE TABLE factor_strategy_decisions (\n\texecution_id UUID NOT NULL, \n\tevent_seq INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tobservation_sha256 VARCHAR(64) NOT NULL, \n\teligibility_sha256 VARCHAR(64) NOT NULL, \n\tscore_sha256 VARCHAR(64) NOT NULL, \n\tallocation_sha256 VARCHAR(64) NOT NULL, \n\treply_sha256 VARCHAR(64) NOT NULL, \n\tsignal_id VARCHAR(64) NOT NULL, \n\trecord JSONB NOT NULL, \n\trecord_canonical TEXT NOT NULL, \n\trecord_sha256 VARCHAR(64) NOT NULL, \n\tPRIMARY KEY (execution_id, event_seq), \n\tUNIQUE (owner_id, execution_id, event_seq), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, execution_id) REFERENCES factor_strategy_execution_outcomes (owner_id, run_id, attempt_id, generation, execution_id), \n\tCHECK (event_seq BETWEEN 0 AND 7 AND generation=1 AND octet_length(record_canonical) BETWEEN 1 AND 1048576 AND jsonb_typeof(record)='object' AND record_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n\n;\n\nCREATE TABLE factor_strategy_orders (\n\texecution_id UUID NOT NULL, \n\tnative_order_id VARCHAR(200) NOT NULL, \n\towner_id UUID NOT NULL, \n\tevent_seq INTEGER NOT NULL, \n\tlogical_order_id VARCHAR(64) NOT NULL, \n\tlisting_id UUID NOT NULL, \n\trecord JSONB NOT NULL, \n\trecord_canonical TEXT NOT NULL, \n\trecord_sha256 VARCHAR(64) NOT NULL, \n\tPRIMARY KEY (execution_id, native_order_id), \n\tUNIQUE (owner_id, execution_id, native_order_id), \n\tFOREIGN KEY(owner_id, execution_id, event_seq) REFERENCES factor_strategy_decisions (owner_id, execution_id, event_seq), \n\tCHECK (octet_length(record_canonical) BETWEEN 1 AND 65536 AND logical_order_id ~ '^[a-f0-9]{64}$' AND record_sha256 ~ '^[a-f0-9]{64}$' AND jsonb_typeof(record)='object')\n)\n\n\n;\n\nCREATE TABLE factor_strategy_fills (\n\texecution_id UUID NOT NULL, \n\tnative_fill_id VARCHAR(200) NOT NULL, \n\towner_id UUID NOT NULL, \n\tnative_order_id VARCHAR(200) NOT NULL, \n\trecord JSONB NOT NULL, \n\trecord_canonical TEXT NOT NULL, \n\trecord_sha256 VARCHAR(64) NOT NULL, \n\tPRIMARY KEY (execution_id, native_fill_id), \n\tFOREIGN KEY(owner_id, execution_id, native_order_id) REFERENCES factor_strategy_orders (owner_id, execution_id, native_order_id), \n\tCHECK (octet_length(record_canonical) BETWEEN 1 AND 65536 AND record_sha256 ~ '^[a-f0-9]{64}$' AND jsonb_typeof(record)='object')\n)\n\n\n;\n"
